      value.events.push({sequence:old.events.length+1,at:value.updatedAt,kind,stepId,callId,detail:clone(detail)});
      this.db.prepare('UPDATE workflow_runs SET value=? WHERE id=?').run(JSON.stringify(value),id);return value;
    });
  }
}

// MIT. Complete saved workflows over the original native console requests.
import { canonical, digest, fail } from './records.mjs';
import { WorkflowRecords, workflowPointer, workflowDispatchActive, registerWorkflowDispatcher } from './workflow-records.mjs';

const clone=value=>JSON.parse(JSON.stringify(value));
const plain=value=>Boolean(value&&typeof value==='object'&&!Array.isArray(value));
const need=(test,code,message)=>{if(!test)throw fail(code,message,409);};
const errorValue=error=>({code:error.code??'CONSOLE_WORKFLOW_ERROR',message:error.message??String(error)});
